export declare function tool<Schema extends AnyZodRawShape>(name: string, description: string, inputSchema: Schema, handler: (args: InferShape<Schema>, extra: RequestHandlerExtra<ServerRequest, ServerNotification>) => Promise<CallToolResult>, extras?: ToolExtras): SdkMcpToolDefinition<Schema>;